      val inheritedMethods = commonInheritedMethods(extendsC, analyzer.traits)
      val dottedMethods = toSet(ti.asInstanceOf[TraitIndex].dottedMethods.secondSet)
      val methods = inheritedMethods ++ dottedMethods
